tool_input.new_string:
handleSave(setLoading) {
  // 汛后检查整改五项在「保存」时也必填（禅道 7008 重新激活：此前校验只挂 beforeSubmit，
  // 而页面唯一入口是保存按钮，留空仍可存成功）。保存 / 提交两链共用 validatePostExtraForm。
  const postError = this.validatePostExtraForm()
  if (postError) { this.msgWarning(postError); return }
  // 检查事项草稿态：允许先不填完，逐项必填在提交前校验（见 beforeSubmit）
  this.itemRequiredError = false
  // 政府侧汛前检查：派出检查组必填（0 是合法值，只有留空才拦）
  this.deployRequiredError = this.isGroupNumRequired && !this.hasGroupNum
  return this.saveFloodRecord(() => (this.buildPayload()), (payload) => (payload.inspectionId ? updateInspection : saveInspection)(payload), setLoading, { allowBlankItems: true })
},
